import{_ as a,o,c as l,a5 as r}from"./chunks/framework.Bt0SrEfo.js";const c=JSON.parse('{"title":"面试技巧大全","description":"","frontmatter":{},"headers":[],"relativePath":"面试/面试技巧/15.线下面试技巧.md","filePath":"面试/面试技巧/15.线下面试技巧.md","lastUpdated":1792500960000}'),e={name:"面试/面试技巧/15.线下面试技巧.md"};function i(d,t,n,h,s,u){return o(),l("div",null,[...t[0]||(t[0]=[r(`<h1 id="面试技巧大全" tabindex="-1">面试技巧大全 <a class="header-anchor" href="#面试技巧大全" aria-label="Permalink to &quot;面试技巧大全&quot;">​</a></h1><blockquote><p>系统整理面试方法论：流程规划、线下面试、远程面试、压力面试、STAR 法则、反问清单。</p></blockquote><hr><h2 id="一、面试流程总览" tabindex="-1">一、面试流程总览 <a class="header-anchor" href="#一、面试流程总览" aria-label="Permalink to &quot;一、面试流程总览&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HR 筛选简历 → 一面（技术基础）→ 二面（项目 + 编码） → 三面（架构 / 终面） → HR 面（谈薪）</span></span>
<span class="line"><span>                  ↓                  ↓                    ↓                  ↓</span></span>
<span class="line"><span>              1 小时              1.5 小时             1-2 小时           30 分钟</span></span></code></pre></div><h3 id="各阶段侧重点" tabindex="-1">各阶段侧重点 <a class="header-anchor" href="#各阶段侧重点" aria-label="Permalink to &quot;各阶段侧重点&quot;">​</a></h3><table tabindex="0"><thead><tr><th>阶段</th><th>重点</th><th>准备</th></tr></thead><tbody><tr><td>HR 面</td><td>软实力 / 沟通 / 稳定性 / 动机</td><td>自我介绍 1 分钟版 + 工作经历</td></tr><tr><td>一面</td><td>技术基础 / 八股文</td><td><a href="./../2-复习清单#🔥-必背高频每天看一遍">复习清单 §必背高频</a></td></tr><tr><td>二面</td><td>项目 + 编码 + 追问</td><td><a href="./../项目/项目经验/">4 个项目经验</a> + 手写题</td></tr><tr><td>三面</td><td>架构 / 系统设计 / 团队 / 业务</td><td>行业理解 + 团队管理（如果有）</td></tr><tr><td>HR 面</td><td>谈薪 / 福利 / 入职</td><td>薪资 offer 准备 + 反问</td></tr></tbody></table><hr><h2 id="二、自我介绍-3-个时长版本" tabindex="-1">二、自我介绍（3 个时长版本） <a class="header-anchor" href="#二、自我介绍-3-个时长版本" aria-label="Permalink to &quot;二、自我介绍（3 个时长版本）&quot;">​</a></h2><h3 id="_1-分钟版-hr-笔试破冰" tabindex="-1">1 分钟版（HR / 笔试破冰） <a class="header-anchor" href="#_1-分钟版-hr-笔试破冰" aria-label="Permalink to &quot;1 分钟版（HR / 笔试破冰）&quot;">​</a></h3><blockquote><p>&quot;你好，我叫 XXX，<strong>7 年</strong>前端经验，做过 <strong>B 端 SaaS、SSR、PWA、跨端 App 和大屏</strong>。</p><p><strong>主力技术栈</strong>：React + TypeScript + Next.js，最近 2 年主导了好几个中后台项目；同时熟悉 <strong>Vue 生态</strong>（Vue 2/3 + Vite），去年主导过一个 <strong>Vue 2 + Webpack 4 → Vue 3 + Vite + Pinia</strong> 迁移，<strong>启动 28 秒 → 0.8 秒</strong>。</p><p><strong>擅长</strong>性能优化和工程化建设，能从源码讲清楚 Webpack Loader/Plugin 链、Vite 的 esbuild 预构建原理。</p><p>这次想找一个<strong>业务更聚焦、有技术挑战</strong>的方向。&quot;</p></blockquote><h3 id="_3-分钟版-技术面最常用" tabindex="-1">3 分钟版（技术面最常用） <a class="header-anchor" href="#_3-分钟版-技术面最常用" aria-label="Permalink to &quot;3 分钟版（技术面最常用）&quot;">​</a></h3><blockquote><p>自我介绍按公式：基本信息 + 技术栈 + 代表项目 + 核心能力 + 求职动机</p></blockquote><p>📚 详细版本：<a href="./../3-自我介绍">自我介绍（3 / 5 分钟版）</a></p><h3 id="_5-分钟版-终面-高-level" tabindex="-1">5 分钟版（终面 / 高 level） <a class="header-anchor" href="#_5-分钟版-终面-高-level" aria-label="Permalink to &quot;5 分钟版（终面 / 高 level）&quot;">​</a></h3><blockquote><p>加上对行业的理解、未来规划、为什么离开、为什么不另选其他公司。</p></blockquote><hr><h2 id="三、线下面试技巧" tabindex="-1">三、线下面试技巧 <a class="header-anchor" href="#三、线下面试技巧" aria-label="Permalink to &quot;三、线下面试技巧&quot;">​</a></h2><h3 id="准备阶段-面试前-1-天" tabindex="-1">准备阶段（面试前 1 天） <a class="header-anchor" href="#准备阶段-面试前-1-天" aria-label="Permalink to &quot;准备阶段（面试前 1 天）&quot;">​</a></h3><ul><li>[ ] 打印 2 份简历（备用准备一份防丢失）</li><li>[ ] 准备纸质笔记本 + 笔（高频被问到就记下来）</li><li>[ ] 规划路线（提前踩点，迟到必扣分）</li><li>[ ] 准备 1 分钟版自我介绍并计时</li><li>[ ] 准备好 4 个项目的&quot;30 秒介绍&quot;</li></ul><h3 id="着装仪表" tabindex="-1">着装仪表 <a class="header-anchor" href="#着装仪表" aria-label="Permalink to &quot;着装仪表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>公司类型</th><th>推荐</th></tr></thead><tbody><tr><td>互联网大厂</td><td>商务休闲 / 简单 T 恤 + 长裤</td></tr><tr><td>外企</td><td>偏正式商务装</td></tr><tr><td>国企 / 银行</td><td>偏正式商务装</td></tr><tr><td>创业公司</td><td>干净整洁</td></tr></tbody></table><h3 id="沟通要点" tabindex="-1">沟通要点 <a class="header-anchor" href="#沟通要点" aria-label="Permalink to &quot;沟通要点&quot;">​</a></h3><ol><li><strong>眼神交流</strong>：看眉心或鼻梁，避免一直盯纸 / 地面</li><li><strong>身体语言</strong>：坐姿自然、适度前倾（表示在听）</li><li><strong>回答结构</strong>：结论先行 + 理由 / 例子支撑</li><li><strong>听不懂的题</strong>：直接说&quot;这块我没深入过，但我猜是 XXX 思路&quot;——展示思考 &gt; 假装懂</li><li><strong>被 challenge</strong>：先肯定再补，&quot;您说得对，我再补充一下...&quot;</li></ol><hr><h2 id="四、远程面试技巧" tabindex="-1">四、远程面试技巧 <a class="header-anchor" href="#四、远程面试技巧" aria-label="Permalink to &quot;四、远程面试技巧&quot;">​</a></h2><h3 id="设备-环境" tabindex="-1">设备 / 环境 <a class="header-anchor" href="#设备-环境" aria-label="Permalink to &quot;设备 / 环境&quot;">​</a></h3><ul><li>[ ] 网络稳定（手机热点备用）</li><li>[ ] 摄像头清晰（背景简洁、自然光优先）</li><li>[ ] 麦克风清晰（耳机优先、提前测音）</li><li>[ ] 桌面整洁（避免私人物品出镜）</li><li>[ ] 关闭无关软件（IM 通知、邮件等）</li></ul><h3 id="工具" tabindex="-1">工具 <a class="header-anchor" href="#工具" aria-label="Permalink to &quot;工具&quot;">​</a></h3><ul><li>主流平台：腾讯会议 / 飞书 / 钉钉 / Zoom，提前 30 分钟测试客户端</li><li>共享屏幕：能熟练切换屏幕（避免展示桌面混乱）</li><li>在线编码：牛客 / CodeSandbox，提前熟悉快捷键</li></ul><h3 id="流程注意" tabindex="-1">流程注意 <a class="header-anchor" href="#流程注意" aria-label="Permalink to &quot;流程注意&quot;">​</a></h3><ul><li>提前 10 分钟进入会议</li><li>面试开始前主动说&quot;老师您好，面试开始时麻烦您说一声&quot;</li><li>卡顿 / 中断时主动说&quot;我这边网络有点问题，能麻烦您重复一下吗&quot;</li><li>共享屏幕前关掉其他标签页、消息通知</li></ul><hr><h2 id="五、压力面试应对" tabindex="-1">五、压力面试应对 <a class="header-anchor" href="#五、压力面试应对" aria-label="Permalink to &quot;五、压力面试应对&quot;">​</a></h2><blockquote><p>⚠️ 高 level 面试官常用：故意质疑你的方案 / 反复追问同一问题 / 表达不友好。</p></blockquote><h3 id="_7-种常见套路-应对" tabindex="-1">7 种常见套路 + 应对 <a class="header-anchor" href="#_7-种常见套路-应对" aria-label="Permalink to &quot;7 种常见套路 + 应对&quot;">​</a></h3><table tabindex="0"><thead><tr><th>套路</th><th>举例</th><th>应对</th></tr></thead><tbody><tr><td><strong>故意质疑</strong></td><td>&quot;你这个方案不行啊...&quot;</td><td>&quot;理解您的考虑，我的设计是 XXX（理由），如果场景是 YYY 我会改成 ZZZ&quot;</td></tr><tr><td><strong>反复追问</strong></td><td>&quot;为什么不是 XXX？&quot;</td><td>不急躁，从不同维度再答一遍</td></tr><tr><td><strong>打断式</strong></td><td>&quot;这个不对，你说重点&quot;</td><td>立即收口，&quot;重点是 XXX&quot;，避免长篇大论</td></tr><tr><td><strong>沉默压力</strong></td><td>答完后等 5 秒不说话</td><td>不主动填满沉默，&quot;还有想问的吗？&quot;或等面试官开口</td></tr><tr><td><strong>连续否定</strong></td><td>&quot;我们不要这种东西&quot;</td><td>不争辩，&quot;明白，那您想要的方向是？&quot;</td></tr><tr><td><strong>拒绝回答</strong></td><td>&quot;你自己想&quot;</td><td>沉默 5 秒后给出假设答案</td></tr><tr><td><strong>超时打断</strong></td><td>答到一半 &quot;下一个题&quot;</td><td>不纠结没答完的部分，转下一题</td></tr></tbody></table><h3 id="核心原则" tabindex="-1">核心原则 <a class="header-anchor" href="#核心原则" aria-label="Permalink to &quot;核心原则&quot;">​</a></h3><ul><li><strong>保持冷静</strong>：不急躁、不反驳、不辩解</li><li><strong>主动为收</strong>：遇到压力测试你立刻认怂或换思路</li><li><strong>展示抗压</strong>：压力下条理清晰 = 真实能力的体现</li></ul><hr><h2 id="六、star-法则完整版" tabindex="-1">六、STAR 法则完整版 <a class="header-anchor" href="#六、star-法则完整版" aria-label="Permalink to &quot;六、STAR 法则完整版&quot;">​</a></h2><blockquote><p>描述&quot;最有挑战的事&quot;、&quot;最有成就的事&quot;必用。</p></blockquote><h3 id="star-四要素" tabindex="-1">STAR 四要素 <a class="header-anchor" href="#star-四要素" aria-label="Permalink to &quot;STAR 四要素&quot;">​</a></h3><table tabindex="0"><thead><tr><th>要素</th><th>含义</th><th>时长占比</th></tr></thead><tbody><tr><td><strong>S</strong>ituation</td><td>背景：项目场景 / 规模 / 复杂度</td><td>10%</td></tr><tr><td><strong>T</strong>ask</td><td>任务：你的角色 / 责任 / 目标</td><td>10%</td></tr><tr><td><strong>A</strong>ction</td><td>行动：技术选型 / 实现 / 关键决策</td><td>70%</td></tr><tr><td><strong>R</strong>esult</td><td>结果：数据化产出 / 业务价值 / 团队收益</td><td>10%</td></tr></tbody></table><h3 id="反例-vs-正例" tabindex="-1">反例 vs 正例 <a class="header-anchor" href="#反例-vs-正例" aria-label="Permalink to &quot;反例 vs 正例&quot;">​</a></h3><h4 id="❌-反例" tabindex="-1">❌ 反例 <a class="header-anchor" href="#❌-反例" aria-label="Permalink to &quot;❌ 反例&quot;">​</a></h4><blockquote><p>&quot;我做过一个性能优化，把启动时间缩短了。&quot;</p></blockquote><h4 id="✅-正例" tabindex="-1">✅ 正例 <a class="header-anchor" href="#✅-正例" aria-label="Permalink to &quot;✅ 正例&quot;">​</a></h4><blockquote><p>&quot;我们接管了一个 <strong>Vue 2 + Webpack 4</strong> 的老项目（<strong>S</strong>：模块 80+，启动 28 秒），我作为前端 owner（<strong>T</strong>），主导了 <strong>Vue 3 + Vite + Pinia</strong> 迁移。<strong>A</strong>：先把 mixin 重构成 Composition API（按 use case 拆分），再做第三方库 ESM 兼容，最后用 <code>shallowRef</code> 优化大列表。<strong>R</strong>：启动时间从 28s 降到 0.8s，HMR 从 2s 降到 50ms。&quot;</p></blockquote><hr><h2 id="七、反问清单-面试官问-你有什么想问的" tabindex="-1">七、反问清单（面试官问&quot;你有什么想问的&quot;） <a class="header-anchor" href="#七、反问清单-面试官问-你有什么想问的" aria-label="Permalink to &quot;七、反问清单（面试官问&quot;你有什么想问的&quot;）&quot;">​</a></h2><blockquote><p>⚠️ 必问 2-3 个。空着不答 = 你不重视这份工作。</p></blockquote><h3 id="按面试阶段选" tabindex="-1">按面试阶段选 <a class="header-anchor" href="#按面试阶段选" aria-label="Permalink to &quot;按面试阶段选&quot;">​</a></h3><h4 id="一面-技术基础" tabindex="-1">一面（技术基础） <a class="header-anchor" href="#一面-技术基础" aria-label="Permalink to &quot;一面（技术基础）&quot;">​</a></h4><ul><li>团队目前前端基建 / CI / 监控体系是什么水平？</li><li>团队有内部技术分享 / 周会机制吗？</li></ul><h4 id="二面-项目-编码" tabindex="-1">二面（项目 / 编码） <a class="header-anchor" href="#二面-项目-编码" aria-label="Permalink to &quot;二面（项目 / 编码）&quot;">​</a></h4><ul><li>我入职后第一个月会负责什么模块？</li><li>团队里有没有资深工程师的话，能讲讲他的成长路径吗？</li></ul><h4 id="三面-架构-终面" tabindex="-1">三面（架构 / 终面） <a class="header-anchor" href="#三面-架构-终面" aria-label="Permalink to &quot;三面（架构 / 终面）&quot;">​</a></h4><ul><li>团队明年的技术规划是什么？</li><li>公司 / 部门目前最大的技术挑战是什么？</li><li>您在团队里最看重工程师的什么品质？</li></ul><h4 id="hr-面-谈薪前" tabindex="-1">HR 面（谈薪前） <a class="header-anchor" href="#hr-面-谈薪前" aria-label="Permalink to &quot;HR 面（谈薪前）&quot;">​</a></h4><ul><li>团队规模和构成？</li><li>工作时间 / 加班强度？</li><li>入职流程大概多久？</li></ul><h3 id="❌-不要问" tabindex="-1">❌ 不要问 <a class="header-anchor" href="#❌-不要问" aria-label="Permalink to &quot;❌ 不要问&quot;">​</a></h3><ul><li>❌ 薪资（HR 面单独议）</li><li>❌ 加班强度（终面或入职前问）</li><li>❌ &quot;您觉得我能过吗&quot;（不专业）</li><li>❌ &quot;贵公司为什么要招这个岗位&quot;（潜台词不好）</li><li>❌ 同时面几家公司（暴露不专注）</li></ul><hr><h2 id="八、面试结束后的复盘" tabindex="-1">八、面试结束后的复盘 <a class="header-anchor" href="#八、面试结束后的复盘" aria-label="Permalink to &quot;八、面试结束后的复盘&quot;">​</a></h2><p>每次面试结束后立刻（30 分钟内）：</p><ol><li><strong>复盘每道题</strong>： <ul><li>答得好的：为什么答得好？</li><li>答得差的：哪一步卡住？怎么改进？</li><li>答错 / 不会的：补到复习清单</li></ul></li><li><strong>记录面试官追问</strong>：补充到项目经验</li><li><strong>整理公司问题</strong>：后面问 HR / 二面参考</li><li><strong>调整自我介绍</strong>：根据面试官反馈微调</li></ol><hr><h2 id="九、面试避坑清单" tabindex="-1">九、面试避坑清单 <a class="header-anchor" href="#九、面试避坑清单" aria-label="Permalink to &quot;九、面试避坑清单&quot;">​</a></h2><ul><li>[ ] 不要迟到（提前 10 分钟到）</li><li>[ ] 不要背简历（讲故事 &gt; 列经历）</li><li>[ ] 不要争辩（&quot;你说得对，我再补充&quot;）</li><li>[ ] 不要过度谦虚（&quot;我做得不够好&quot;）</li><li>[ ] 不要提别人（同事 / 领导 / 前公司）</li><li>[ ] 不要问薪资（一面不问、二面可议、HR 面谈）</li><li>[ ] 不要&quot;我不会&quot;——&quot;我没深入过，但我的理解是...&quot;</li><li>[ ] 不要长时间沉默——主动问&quot;这块能给我点提示吗&quot;</li><li>[ ] 不要说&quot;我要看公司发展&quot;——&quot;我想要稳定发展&quot;比&quot;公司给我什么&quot;</li></ul><h2 id="🔗-相关文档" tabindex="-1">🔗 相关文档 <a class="header-anchor" href="#🔗-相关文档" aria-label="Permalink to &quot;🔗 相关文档&quot;">​</a></h2><ul><li><a href="./../3-自我介绍">自我介绍（3 / 5 分钟版）</a></li><li><a href="./../2-复习清单">复习清单</a></li><li><a href="./../薪资offer/14.薪资offer">薪资谈判</a></li><li><a href="./../工作经历/">工作经历问题准备</a></li></ul>`,72)])])}const b=a(e,[["render",i]]);export{c as __pageData,b as default};
